/**
 * Turns a loaded room GLB + its room definition (rooms/<id>.js) into what WorldEngine
 * needs: collision boxes, room bounds, seats, spawn points, walkable floors, the hero
 * camera and the anchors, plus the per-room material treatment (baked = unlit,
 * EMIT_* = HDR emissive with per-room levels, colour grade tints).
 *
 * Layout source: def.layout (generated by the Blender build script, Babylon world
 * space). parseGlbLayout() reads the same data from helper nodes in the GLB
 * (COL_*, ROOM_BOUNDS, SEAT_*, SPAWN_*, CAM_hero*); it is the phase 1 path, kept as a
 * fallback and so the dev harness can check a layout module against its GLB.
 */
import { Vector3 } from "@babylonjs/core/Maths/math.vector";
import { Color3 } from "@babylonjs/core/Maths/math.color";
import { Constants } from "@babylonjs/core/Engines/constants";
import { makeBox } from "../collision.js";

export { groundAt } from "./ground.js";

/** Phase 1 reading of a room GLB's helper nodes (exact same maths as before). */
export function parseGlbLayout(container) {
  const boxes = [];
  const seats = [];
  const spawns = [];
  let bounds = null;
  const nodes = [...container.transformNodes, ...container.meshes];
  const byName = new Map(nodes.map((n) => [n.name, n]));
  for (const n of nodes) n.computeWorldMatrix?.(true);
  for (const m of container.meshes) {
    const name = m.name || "";
    if (!(name.startsWith("COL_") || name === "ROOM_BOUNDS")) continue;
    m.computeWorldMatrix(true);
    const bb = m.getBoundingInfo().boundingBox;
    if (name === "ROOM_BOUNDS") {
      bounds = { minX: bb.minimumWorld.x, maxX: bb.maximumWorld.x, minY: bb.minimumWorld.y, maxY: bb.maximumWorld.y, minZ: bb.minimumWorld.z, maxZ: bb.maximumWorld.z };
    } else {
      // oriented box in the floor plane from the world matrix
      const wm = m.getWorldMatrix();
      const c = bb.centerWorld;
      const ax = Vector3.TransformNormal(new Vector3(1, 0, 0), wm);
      const az = Vector3.TransformNormal(new Vector3(0, 0, 1), wm);
      const ext = bb.extendSize;
      const hx = Math.hypot(ax.x, ax.z) * ext.x;
      const hz = Math.hypot(az.x, az.z) * ext.z;
      const angle = Math.atan2(ax.z, ax.x);
      boxes.push({ name: name.slice(4), ...makeBox(c.x, c.z, hx, hz, -angle) });
    }
  }
  for (const [name, n] of byName) {
    const mm = /^SEAT_(.+)_(\d+)$/.exec(name);
    if (mm) {
      const look = byName.get(`${name}_look`);
      const p = n.getAbsolutePosition().clone();
      const q = look ? look.getAbsolutePosition() : p.add(new Vector3(0, 0, 1));
      const yaw = Math.atan2(q.x - p.x, q.z - p.z);
      seats.push({ name, pos: new Vector3(p.x, 0, p.z), height: p.y, yaw });
    }
    if (/^SPAWN_\d+$/.test(name)) spawns.push(n.getAbsolutePosition().clone());
  }
  // byte order, same as the build script and the server-side seat indexes
  seats.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  const hero = byName.get("CAM_hero");
  const heroT = byName.get("CAM_hero_target");
  return {
    boxes,
    seats,
    spawns,
    bounds,
    hero: hero && heroT ? { pos: hero.getAbsolutePosition().clone(), target: heroT.getAbsolutePosition().clone() } : null,
    floors: [],
  };
}

const v3 = (a) => new Vector3(a[0], a[1], a[2]);

/** Layout module (plain data) -> runtime objects. */
export function layoutFromData(layout) {
  const seats = (layout.seats || []).map((s) => ({
    name: s.name,
    type: s.type,
    pos: v3(s.pos),
    height: s.height,
    yaw: s.yaw,
    approach: s.approach ? new Vector3(s.approach[0], 0, s.approach[1]) : null,
    data: s,
  }));
  // byte order (same rule as parseGlbLayout): seat indexes are positions in this list
  seats.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  return {
    boxes: (layout.colliders || []).map((c) => ({ name: c.name, ...makeBox(c.cx, c.cz, c.hx, c.hz, c.angle) })),
    seats,
    spawns: (layout.spawns || []).map(v3),
    bounds: layout.bounds ? { ...layout.bounds } : null,
    hero: layout.hero ? { pos: v3(layout.hero.pos), target: v3(layout.hero.target), fov: layout.hero.fov } : null,
    floors: (layout.floors || []).map((f) => ({ ...f })),
  };
}

/**
 * Hides helper meshes, applies the room's material treatment and returns the room
 * state: { boxes, bounds, seats, spawns, floors, hero, floor, lampPositions, anchors }.
 */
export function prepareRoom(container, def) {
  const look = def.look || {};
  const fromGlb = parseGlbLayout(container);
  const L = def.layout ? layoutFromData(def.layout) : fromGlb;
  const pickable = look.pickable ? new RegExp(look.pickable, "i") : /^FLOOR$/;
  const tints = look.bakedTint || {};
  const levels = look.emissive || {};
  const doubleSided = new Set(look.doubleSided || []);
  const alphaTest = new Set(look.alphaTest || []);
  const additive = new Set(look.additive || []);
  for (const m of container.meshes) {
    const name = m.name || "";
    if (name.startsWith("COL_") || name === "ROOM_BOUNDS") {
      m.isVisible = false;
      m.isPickable = false;
      continue;
    }
    m.isPickable = pickable.test(name);
    m.freezeWorldMatrix?.();
    m.doNotSyncBoundingInfo = true;
    const mat = m.material;
    if (!mat) continue;
    const mname = mat.name || "";
    if (mname.startsWith("BAKED_")) {
      if ("unlit" in mat) mat.unlit = true;
      mat.backFaceCulling = !doubleSided.has(mname);
      if (mat.albedoTexture) mat.albedoTexture.anisotropicFilteringLevel = 8;
      const g = tints[name] || tints[mname];
      if (g && "albedoColor" in mat) mat.albedoColor = new Color3(g[0], g[1], g[2]);
      // a baked light layer rides in the emissive slot: dark until the runtime sets its level
      if (mat.emissiveTexture && "emissiveColor" in mat) {
        mat.emissiveColor = Color3.Black();
        m.metadata = { ...(m.metadata || {}), lightLayer: mat.metadata?.gltf?.extras?.descall_layer || def.lightLayer || "layer" };
      }
    } else if (mname.startsWith("EMIT_")) {
      if ("unlit" in mat) mat.unlit = false;
      mat.emissiveIntensity = levels[mname] ?? look.emissiveDefault ?? 1.5;
      if ("albedoColor" in mat) mat.albedoColor = Color3.Black();
      if (additive.has(mname)) {
        // black = clear (aurora, moon disc, flames): added on top of what is behind
        mat.transparencyMode = 2; // ALPHABLEND
        mat.alpha = 0.999;
        mat.alphaMode = Constants.ALPHA_ADD;
        mat.backFaceCulling = false;
        mat.disableDepthWrite = true;
        m.isPickable = false;
      }
      if (alphaTest.has(mname) && mat.emissiveTexture) {
        mat.opacityTexture = null;
        mat.albedoTexture = mat.emissiveTexture;
        mat.useAlphaFromAlbedoTexture = true;
        mat.transparencyMode = 1; // ALPHATEST
        mat.alphaCutOff = 0.5;
      }
    }
  }
  const lampRe = look.lights?.lamps?.match ? new RegExp(look.lights.lamps.match) : null;
  return {
    boxes: L.boxes,
    bounds: L.bounds || fromGlb.bounds || { minX: -3, maxX: 3, minY: 0, maxY: 3, minZ: -3, maxZ: 3 },
    seats: L.seats,
    spawns: L.spawns,
    floors: L.floors,
    hero: L.hero,
    floor: container.meshes.find((m) => m.name === "FLOOR") || null,
    lampPositions: lampRe ? container.meshes.filter((m) => lampRe.test(m.name)).map((m) => ({ name: m.name, pos: m.getBoundingInfo().boundingBox.centerWorld.clone() })) : [],
    anchors: def.layout?.anchors || {},
    glbLayout: fromGlb,
  };
}
